export const MIGRATIONS: { name: string; sql: string }[] = [{"name":"20261119000000_initial_schema.sql","sql":"-- =====================================================================\n-- Apna Okara: initial database schema (Phase 1)\n-- Run in Supabase: SQL Editor -> paste -> Run   (or `supabase db push`)\n--\n-- Rules:\n--  * Nothing is hard-deleted. Status columns control what the public sees.\n--  * The website server and admin panel use the service role key, which\n--    bypasses Row Level Security (RLS). The public (anon key) can only READ\n--    what the policies below allow.\n-- =====================================================================\n\ncreate extension if not exists pgcrypto;\n\n-- ---------------------------------------------------------------------\n-- Enums\n-- ---------------------------------------------------------------------\ncreate type model_type as enum ('buy_sell','vehicles','property','jobs','services','business');\ncreate type listing_status as enum ('pending','approved','rejected','expired','removed','sold');\ncreate type payment_status as enum ('pending','verified','rejected','free');\ncreate type payment_method as enum ('jazzcash','easypaisa','bank','free');\ncreate type admin_role as enum ('super_admin','moderator','blog_writer','rishta_coordinator');\ncreate type field_type as enum ('text','number','select','boolean','year');\ncreate type banner_status as enum ('pending','scheduled','running','paused','expired','rejected');\ncreate type publish_status as enum ('draft','scheduled','published','archived');\ncreate type rishta_status as enum ('pending','approved','rejected','expired','hidden','removed');\ncreate type interest_status as enum ('sent','accepted','declined','withdrawn');\n\n-- ---------------------------------------------------------------------\n-- Helper: updated_at trigger\n-- ---------------------------------------------------------------------\ncreate or replace function set_updated_at() returns trigger\nlanguage plpgsql as $$\nbegin\n  new.updated_at = now();\n  return new;\nend $$;\n\n-- ---------------------------------------------------------------------\n-- Admin users and activity log\n-- ---------------------------------------------------------------------\ncreate table admin_users (\n  id uuid primary key references auth.users(id) on delete cascade,\n  full_name text not null,\n  role admin_role not null default 'moderator',\n  is_active boolean not null default true,\n  created_at timestamptz not null default now()\n);\n\ncreate or replace function is_admin(required admin_role default null) returns boolean\nlanguage sql stable security definer set search_path = public as $$\n  select exists (\n    select 1 from admin_users a\n    where a.id = auth.uid() and a.is_active\n      and (required is null or a.role = required or a.role = 'super_admin')\n  );\n$$;\n\ncreate table activity_log (\n  id bigint generated always as identity primary key,\n  admin_id uuid references admin_users(id),\n  action text not null,              -- e.g. 'listing.approve'\n  entity text not null,              -- e.g. 'listings'\n  entity_id text,\n  details jsonb not null default '{}',\n  created_at timestamptz not null default now()\n);\ncreate index on activity_log (entity, entity_id);\n\n-- ---------------------------------------------------------------------\n-- Locations\n-- ---------------------------------------------------------------------\ncreate table districts (\n  id smallint generated always as identity primary key,\n  slug text unique not null,\n  name_en text not null,\n  name_ur text not null,\n  sort_order int not null default 0,\n  is_active boolean not null default true\n);\n\ncreate table cities (\n  id smallint generated always as identity primary key,\n  district_id smallint not null references districts(id),\n  slug text unique not null,\n  name_en text not null,\n  name_ur text not null,\n  sort_order int not null default 0,\n  is_active boolean not null default true\n);\n\ncreate table localities (\n  id int generated always as identity primary key,\n  city_id smallint not null references cities(id),\n  slug text not null,\n  name_en text not null,\n  name_ur text not null,\n  sort_order int not null default 0,\n  is_active boolean not null default true,\n  unique (city_id, slug)\n);\n\n-- ---------------------------------------------------------------------\n-- Categories and category-specific fields\n-- ---------------------------------------------------------------------\ncreate table categories (\n  id int generated always as identity primary key,\n  parent_id int references categories(id),\n  model model_type not null,\n  slug text unique not null,\n  name_en text not null,\n  name_ur text not null,\n  icon text,\n  show_on_home boolean not null default false,\n  sort_order int not null default 0,\n  is_active boolean not null default true,\n  seo_title text,\n  seo_description text,\n  created_at timestamptz not null default now()\n);\ncreate index on categories (parent_id);\n\ncreate table category_fields (\n  id int generated always as identity primary key,\n  category_id int not null references categories(id),\n  key text not null,\n  label_en text not null,\n  label_ur text not null,\n  type field_type not null,\n  options jsonb,                     -- [{en,ur}] for select\n  unit_en text,\n  unit_ur text,\n  is_required boolean not null default false,\n  sort_order int not null default 0,\n  unique (category_id, key)\n);\n\n-- ---------------------------------------------------------------------\n-- Pricing and add-ons (admin editable)\n-- ---------------------------------------------------------------------\ncreate table pricing (\n  id int generated always as identity primary key,\n  model model_type,                  -- default price for a model\n  category_id int references categories(id), -- override for one category\n  duration_days int not null,\n  price int not null check (price >= 0),\n  is_active boolean not null default true,\n  unique nulls not distinct (model, category_id, duration_days)\n);\n\ncreate table addons (\n  key text primary key,              -- 'featured', 'whatsapp_boost'\n  name_en text not null,\n  name_ur text not null,\n  price int not null check (price >= 0),\n  is_active boolean not null default true\n);\n\ncreate table promo_codes (\n  id int generated always as identity primary key,\n  code text unique not null,\n  discount_percent int check (discount_percent between 0 and 100),\n  discount_amount int check (discount_amount >= 0),\n  max_uses int,\n  used_count int not null default 0,\n  valid_from timestamptz,\n  valid_to timestamptz,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------------\n-- Listings (all 6 models: ads, service providers, businesses)\n-- ---------------------------------------------------------------------\ncreate sequence listing_ref_seq start 10001;\n\ncreate table listings (\n  id uuid primary key default gen_random_uuid(),\n  reference text unique not null default ('AO-' || nextval('listing_ref_seq')),\n  model model_type not null,\n  category_id int not null references categories(id),\n  subcategory_id int references categories(id),\n  slug text not null,\n  title text not null check (char_length(title) between 5 and 120),\n  description text not null default '',\n  price int check (price >= 0),\n  price_type text not null default 'fixed' check (price_type in ('fixed','negotiable','contact','free')),\n  city_id smallint not null references cities(id),\n  locality_id int references localities(id),\n  custom_fields jsonb not null default '{}',\n\n  -- seller / provider (never login; managed with reference + phone)\n  seller_name text not null,\n  seller_phone text not null,\n  whatsapp_phone text,\n  show_phone boolean not null default true,\n\n  -- plan\n  duration_days int not null,\n  is_featured boolean not null default false,\n  featured_until timestamptz,\n  whatsapp_boost boolean not null default false,\n  is_free boolean not null default false,       -- given free (Free Mode or admin)\n\n  -- workflow\n  status listing_status not null default 'pending',\n  reject_reason text,\n  approved_at timestamptz,\n  approved_by uuid references admin_users(id),\n  expires_at timestamptz,\n  sold_at timestamptz,\n\n  -- service provider / business extras\n  is_verified boolean not null default false,\n  rating_avg numeric(2,1) not null default 0,\n  rating_count int not null default 0,\n\n  views int not null default 0,\n  locale text not null default 'en',\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on listings (status, model, category_id, city_id);\ncreate index on listings (status, is_featured, approved_at desc);\ncreate index on listings (seller_phone);\ncreate index on listings (expires_at) where status = 'approved';\ncreate trigger listings_updated before update on listings for each row execute function set_updated_at();\n\ncreate table listing_images (\n  id bigint generated always as identity primary key,\n  listing_id uuid not null references listings(id),\n  storage_path text not null,\n  sort_order int not null default 0,\n  is_cover boolean not null default false,\n  deleted_at timestamptz,            -- extra photos removed 30 days after expiry\n  created_at timestamptz not null default now()\n);\ncreate index on listing_images (listing_id);\n\ncreate table listing_history (\n  id bigint generated always as identity primary key,\n  listing_id uuid not null references listings(id),\n  event text not null,               -- created, approved, rejected, extended, renewed, sold, expired...\n  details jsonb not null default '{}',\n  admin_id uuid references admin_users(id),\n  created_at timestamptz not null default now()\n);\ncreate index on listing_history (listing_id);\n\n-- ---------------------------------------------------------------------\n-- Payments (kept forever)\n-- ---------------------------------------------------------------------\ncreate table payments (\n  id uuid primary key default gen_random_uuid(),\n  purpose text not null check (purpose in ('listing','renewal','featured','whatsapp_boost','banner','rishta')),\n  listing_id uuid references listings(id),\n  banner_id uuid,                    -- fk added after banners table\n  rishta_profile_id uuid,            -- fk added after rishta table\n  amount int not null check (amount >= 0),\n  method payment_method not null,\n  transaction_id text,\n  paid_from text,                    -- name / number of payer\n  screenshot_path text,\n  promo_code_id int references promo_codes(id),\n  status payment_status not null default 'pending',\n  reject_reason text,\n  verified_by uuid references admin_users(id),\n  verified_at timestamptz,\n  created_at timestamptz not null default now()\n);\ncreate index on payments (status, created_at desc);\n-- Warn on duplicate transaction IDs (same ID used twice = likely fraud)\ncreate index on payments (lower(transaction_id));\n\n-- ---------------------------------------------------------------------\n-- Reviews (service providers and businesses)\n-- ---------------------------------------------------------------------\ncreate table reviews (\n  id bigint generated always as identity primary key,\n  listing_id uuid not null references listings(id),\n  reviewer_name text not null,\n  reviewer_phone text not null,      -- never public\n  rating smallint not null check (rating between 1 and 5),\n  comment text,\n  provider_reply text,\n  is_hidden boolean not null default false,\n  created_at timestamptz not null default now(),\n  unique (listing_id, reviewer_phone)\n);\n\n-- ---------------------------------------------------------------------\n-- Reports and blocklist\n-- ---------------------------------------------------------------------\ncreate table reports (\n  id bigint generated always as identity primary key,\n  listing_id uuid not null references listings(id),\n  reason text not null check (reason in ('fraud','wrong_category','sold','offensive','duplicate','other')),\n  details text,\n  reporter_phone text,\n  status text not null default 'open' check (status in ('open','actioned','dismissed')),\n  handled_by uuid references admin_users(id),\n  created_at timestamptz not null default now()\n);\n\ncreate table blocked_phones (\n  phone text primary key,\n  reason text,\n  blocked_by uuid references admin_users(id),\n  created_at timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------------\n-- Banners (brand ads and our own hero slides / house banners)\n-- ---------------------------------------------------------------------\ncreate table banners (\n  id uuid primary key default gen_random_uuid(),\n  owner_type text not null check (owner_type in ('brand','house')),\n  placement text not null check (placement in ('hero_slider','hero_side','home_strip','category_top','in_feed','ad_detail','app_home','popup')),\n  business_name text,\n  contact_name text,\n  contact_phone text,\n  title_en text,\n  title_ur text,\n  subtitle_en text,\n  subtitle_ur text,\n  button_en text,\n  button_ur text,\n  link_url text,\n  image_desktop_path text,\n  image_mobile_path text,\n  target_city_ids smallint[],        -- null = all cities\n  target_category_ids int[],         -- null = all categories\n  target_platform text not null default 'both' check (target_platform in ('web','app','both')),\n  starts_at timestamptz,\n  ends_at timestamptz,\n  sort_order int not null default 0,\n  status banner_status not null default 'pending',\n  is_free boolean not null default false,\n  needs_design boolean not null default false,\n  stats_token text unique default encode(gen_random_bytes(12), 'hex'), -- private stats link for brand\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate trigger banners_updated before update on banners for each row execute function set_updated_at();\nalter table payments add constraint payments_banner_fk foreign key (banner_id) references banners(id);\n\ncreate table banner_stats (\n  banner_id uuid not null references banners(id),\n  day date not null,\n  views int not null default 0,\n  clicks int not null default 0,\n  primary key (banner_id, day)\n);\n\n-- ---------------------------------------------------------------------\n-- Home page manager, static pages, SEO, settings\n-- ---------------------------------------------------------------------\ncreate table homepage_sections (\n  key text primary key,              -- 'hero', 'categories', 'featured', ...\n  title_en text,\n  title_ur text,\n  is_enabled boolean not null default true,\n  sort_order int not null default 0,\n  config jsonb not null default '{}'\n);\n\ncreate table pages (\n  id int generated always as identity primary key,\n  slug text unique not null,         -- 'about', 'terms', ...\n  title_en text not null,\n  title_ur text not null,\n  body_en text not null default '',\n  body_ur text not null default '',\n  seo_title text,\n  seo_description text,\n  status publish_status not null default 'draft',\n  updated_at timestamptz not null default now()\n);\ncreate trigger pages_updated before update on pages for each row execute function set_updated_at();\n\ncreate table redirects (\n  id int generated always as identity primary key,\n  from_path text unique not null,\n  to_path text not null,\n  status_code smallint not null default 301\n);\n\ncreate table site_settings (\n  key text primary key,\n  value jsonb not null,\n  updated_at timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------------\n-- Blog\n-- ---------------------------------------------------------------------\ncreate table authors (\n  id int generated always as identity primary key,\n  name text not null,\n  bio text,\n  photo_path text\n);\n\ncreate table blog_categories (\n  id int generated always as identity primary key,\n  slug text unique not null,\n  name_en text not null,\n  name_ur text not null\n);\n\ncreate table blog_tags (\n  id int generated always as identity primary key,\n  slug text unique not null,\n  name text not null\n);\n\ncreate table blog_posts (\n  id uuid primary key default gen_random_uuid(),\n  slug text unique not null,\n  locale text not null default 'en' check (locale in ('en','ur')),\n  title text not null,\n  excerpt text,\n  body text not null default '',\n  cover_path text,\n  category_id int references blog_categories(id),\n  author_id int references authors(id),\n  faq jsonb not null default '[]',   -- [{q,a}] -> FAQPage schema\n  seo_title text,\n  seo_description text,\n  focus_keyword text,\n  noindex boolean not null default false,\n  status publish_status not null default 'draft',\n  published_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate trigger blog_posts_updated before update on blog_posts for each row execute function set_updated_at();\n\ncreate table blog_post_tags (\n  post_id uuid references blog_posts(id),\n  tag_id int references blog_tags(id),\n  primary key (post_id, tag_id)\n);\n\n-- ---------------------------------------------------------------------\n-- Rishta (Phase 7). Strictly private: NO public policies.\n-- ---------------------------------------------------------------------\ncreate sequence rishta_ref_seq start 1001;\n\ncreate table rishta_accounts (\n  id uuid primary key references auth.users(id) on delete cascade,\n  phone text unique not null,\n  is_blocked boolean not null default false,\n  created_at timestamptz not null default now()\n);\n\ncreate table rishta_profiles (\n  id uuid primary key default gen_random_uuid(),\n  reference text unique not null default ('R-' || nextval('rishta_ref_seq')),\n  account_id uuid not null references rishta_accounts(id),\n  created_by text not null check (created_by in ('self','parent','sibling','relative')),\n  gender text not null check (gender in ('male','female')),\n  date_of_birth date not null,       -- 18+ enforced by trigger below\n  height_cm smallint,\n  complexion text,\n  marital_status text not null check (marital_status in ('never_married','divorced','widowed')),\n  children smallint not null default 0,\n  religion text,\n  sect text,\n  caste text,\n  education text,\n  profession text,\n  income_range text,\n  native_city_id smallint references cities(id),\n  native_locality_id int references localities(id),\n  current_city text,\n  current_country text not null default 'Pakistan',\n  house_type text check (house_type in ('own','rented','family')),\n  father_profession text,\n  mother_profession text,\n  brothers smallint,\n  sisters smallint,\n  married_siblings smallint,\n  family_type text check (family_type in ('joint','separate')),\n  about text,\n  looking_for jsonb not null default '{}',\n  guardian_name text not null,        -- private\n  guardian_phone text not null,       -- private\n  is_premium boolean not null default false,\n  premium_until timestamptz,\n  status rishta_status not null default 'pending',\n  reject_reason text,\n  verified_by uuid references admin_users(id),\n  approved_at timestamptz,\n  expires_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate trigger rishta_profiles_updated before update on rishta_profiles for each row execute function set_updated_at();\n\ncreate or replace function rishta_check_age() returns trigger\nlanguage plpgsql as $$\nbegin\n  if new.date_of_birth > (current_date - interval '18 years') then\n    raise exception 'Rishta profile must be 18 years or older';\n  end if;\n  return new;\nend $$;\ncreate trigger rishta_profiles_age before insert or update of date_of_birth on rishta_profiles\n  for each row execute function rishta_check_age();\nalter table payments add constraint payments_rishta_fk foreign key (rishta_profile_id) references rishta_profiles(id);\n\ncreate table rishta_photos (\n  id bigint generated always as identity primary key,\n  profile_id uuid not null references rishta_profiles(id),\n  storage_path text not null,\n  is_approved boolean not null default false,\n  approved_by uuid references admin_users(id),\n  created_at timestamptz not null default now()\n);\n\ncreate table rishta_photo_access (\n  profile_id uuid references rishta_profiles(id),\n  viewer_profile_id uuid references rishta_profiles(id),\n  granted_at timestamptz not null default now(),\n  primary key (profile_id, viewer_profile_id)\n);\n\ncreate table rishta_interests (\n  id bigint generated always as identity primary key,\n  from_profile_id uuid not null references rishta_profiles(id),\n  to_profile_id uuid not null references rishta_profiles(id),\n  status interest_status not null default 'sent',\n  mediation_requested boolean not null default false,\n  responded_at timestamptz,\n  created_at timestamptz not null default now(),\n  unique (from_profile_id, to_profile_id),\n  check (from_profile_id <> to_profile_id)\n);\n\ncreate table rishta_reports (\n  id bigint generated always as identity primary key,\n  profile_id uuid not null references rishta_profiles(id),\n  reported_by uuid references rishta_profiles(id),\n  reason text not null,\n  status text not null default 'open' check (status in ('open','actioned','dismissed')),\n  created_at timestamptz not null default now()\n);\n\ncreate table rishta_blocks (\n  blocker_profile_id uuid references rishta_profiles(id),\n  blocked_profile_id uuid references rishta_profiles(id),\n  created_at timestamptz not null default now(),\n  primary key (blocker_profile_id, blocked_profile_id)\n);\n\n-- ---------------------------------------------------------------------\n-- Public views (safe columns only: never phone of hidden sellers etc.)\n-- ---------------------------------------------------------------------\ncreate view public_listings with (security_invoker = true) as\nselect\n  l.id, l.reference, l.model, l.category_id, l.subcategory_id, l.slug, l.title,\n  l.description, l.price, l.price_type, l.city_id, l.locality_id, l.custom_fields,\n  l.seller_name,\n  case when l.show_phone then l.seller_phone end as seller_phone,\n  l.whatsapp_phone,\n  l.is_featured and coalesce(l.featured_until > now(), true) as is_featured,\n  l.is_verified, l.rating_avg, l.rating_count, l.views,\n  l.approved_at, l.expires_at, l.created_at\nfrom listings l\nwhere l.status = 'approved' and (l.expires_at is null or l.expires_at > now());\n\n-- ---------------------------------------------------------------------\n-- Row Level Security\n-- ---------------------------------------------------------------------\nalter table admin_users enable row level security;\nalter table activity_log enable row level security;\nalter table districts enable row level security;\nalter table cities enable row level security;\nalter table localities enable row level security;\nalter table categories enable row level security;\nalter table category_fields enable row level security;\nalter table pricing enable row level security;\nalter table addons enable row level security;\nalter table promo_codes enable row level security;\nalter table listings enable row level security;\nalter table listing_images enable row level security;\nalter table listing_history enable row level security;\nalter table payments enable row level security;\nalter table reviews enable row level security;\nalter table reports enable row level security;\nalter table blocked_phones enable row level security;\nalter table banners enable row level security;\nalter table banner_stats enable row level security;\nalter table homepage_sections enable row level security;\nalter table pages enable row level security;\nalter table redirects enable row level security;\nalter table site_settings enable row level security;\nalter table authors enable row level security;\nalter table blog_categories enable row level security;\nalter table blog_tags enable row level security;\nalter table blog_posts enable row level security;\nalter table blog_post_tags enable row level security;\nalter table rishta_accounts enable row level security;\nalter table rishta_profiles enable row level security;\nalter table rishta_photos enable row level security;\nalter table rishta_photo_access enable row level security;\nalter table rishta_interests enable row level security;\nalter table rishta_reports enable row level security;\nalter table rishta_blocks enable row level security;\n\n-- Public read: reference data\ncreate policy \"public read districts\" on districts for select using (is_active);\ncreate policy \"public read cities\" on cities for select using (is_active);\ncreate policy \"public read localities\" on localities for select using (is_active);\ncreate policy \"public read categories\" on categories for select using (is_active);\ncreate policy \"public read category_fields\" on category_fields for select using (true);\ncreate policy \"public read pricing\" on pricing for select using (is_active);\ncreate policy \"public read addons\" on addons for select using (is_active);\ncreate policy \"public read homepage\" on homepage_sections for select using (is_enabled);\ncreate policy \"public read pages\" on pages for select using (status = 'published');\ncreate policy \"public read redirects\" on redirects for select using (true);\ncreate policy \"public read blog categories\" on blog_categories for select using (true);\ncreate policy \"public read blog tags\" on blog_tags for select using (true);\ncreate policy \"public read authors\" on authors for select using (true);\ncreate policy \"public read blog posts\" on blog_posts for select using (status = 'published' and published_at <= now());\ncreate policy \"public read blog post tags\" on blog_post_tags for select using (true);\n\n-- Public settings only (keys starting with 'public.')\ncreate policy \"public read settings\" on site_settings for select using (key like 'public.%');\n\n-- Public read: live listings and their images\ncreate policy \"public read live listings\" on listings for select\n  using (status = 'approved' and (expires_at is null or expires_at > now()));\ncreate policy \"public read live listing images\" on listing_images for select\n  using (deleted_at is null and exists (\n    select 1 from listings l where l.id = listing_id\n      and l.status = 'approved' and (l.expires_at is null or l.expires_at > now())));\ncreate policy \"public read reviews\" on reviews for select using (not is_hidden);\n\n-- Running banners\ncreate policy \"public read running banners\" on banners for select\n  using (status = 'running' and (starts_at is null or starts_at <= now()) and (ends_at is null or ends_at > now()));\n\n-- Admins can read everything (writes go through the server with service role)\ncreate policy \"admin read listings\" on listings for select using (is_admin());\ncreate policy \"admin read payments\" on payments for select using (is_admin());\ncreate policy \"admin read history\" on listing_history for select using (is_admin());\ncreate policy \"admin read reports\" on reports for select using (is_admin());\ncreate policy \"admin read activity\" on activity_log for select using (is_admin('super_admin'));\ncreate policy \"admin read self\" on admin_users for select using (id = auth.uid() or is_admin('super_admin'));\n\n-- Rishta: no public policies. Member policies are added in Phase 7.\n\n-- ---------------------------------------------------------------------\n-- Auto-expiry (runs hourly with pg_cron)\n-- ---------------------------------------------------------------------\ncreate or replace function expire_listings() returns int\nlanguage plpgsql security definer set search_path = public as $$\ndeclare n int;\nbegin\n  with expired as (\n    update listings set status = 'expired'\n    where status = 'approved' and expires_at is not null and expires_at <= now()\n    returning id\n  )\n  insert into listing_history (listing_id, event)\n  select id, 'expired' from expired;\n  get diagnostics n = row_count;\n\n  -- Featured flag ends with its own date\n  update listings set is_featured = false\n  where is_featured and featured_until is not null and featured_until <= now();\n\n  -- Keep cover photo forever; mark other photos for deletion 30 days after expiry\n  update listing_images i set deleted_at = now()\n  from listings l\n  where i.listing_id = l.id and l.status = 'expired' and not i.is_cover\n    and i.deleted_at is null and l.expires_at <= now() - interval '30 days';\n\n  -- Banners\n  update banners set status = 'expired'\n  where status in ('running','scheduled') and ends_at is not null and ends_at <= now();\n  update banners set status = 'running'\n  where status = 'scheduled' and (starts_at is null or starts_at <= now());\n\n  -- Rishta profiles\n  update rishta_profiles set status = 'expired'\n  where status = 'approved' and expires_at is not null and expires_at <= now();\n\n  return n;\nend $$;\n\n-- Enable pg_cron in Supabase: Database -> Extensions -> pg_cron, then run:\n--   select cron.schedule('expire-listings', '0 * * * *', 'select expire_listings()');\n"},{"name":"20261120000000_reviews_ratings.sql","sql":"-- =====================================================================\n-- Phase 5: ratings and reviews for service providers and businesses\n-- =====================================================================\n\n-- Review moderation details\nalter table reviews add column if not exists provider_reply_at timestamptz;\nalter table reviews add column if not exists hidden_reason text;\nalter table reviews add column if not exists hidden_by uuid references admin_users(id);\ncreate index if not exists reviews_listing_idx on reviews (listing_id, created_at desc);\n\n-- Keep listings.rating_avg / rating_count correct (only visible reviews count)\ncreate or replace function refresh_listing_rating(p_listing uuid) returns void\nlanguage sql as $$\n  update listings l set\n    rating_avg = coalesce((select round(avg(rating)::numeric, 1) from reviews r where r.listing_id = p_listing and not r.is_hidden), 0),\n    rating_count = (select count(*) from reviews r where r.listing_id = p_listing and not r.is_hidden)\n  where l.id = p_listing;\n$$;\n\ncreate or replace function reviews_after_change() returns trigger\nlanguage plpgsql as $$\nbegin\n  if tg_op = 'DELETE' then\n    perform refresh_listing_rating(old.listing_id);\n    return old;\n  end if;\n  perform refresh_listing_rating(new.listing_id);\n  return new;\nend $$;\n\ndrop trigger if exists reviews_rating_refresh on reviews;\ncreate trigger reviews_rating_refresh after insert or update or delete on reviews\n  for each row execute function reviews_after_change();\n\n-- Verified badge history\nalter table listings add column if not exists verified_at timestamptz;\nalter table listings add column if not exists verified_by uuid references admin_users(id);\n"},{"name":"20261121000000_payments_banners.sql","sql":"-- =====================================================================\n-- Phase 6: Featured / WhatsApp Boost add-ons, promo codes, payment\n-- details, banner prices and banner booking.\n-- =====================================================================\n\n-- Add-ons requested on an ad (applied when the payment is verified / ad approved)\nalter table listings add column if not exists featured_requested boolean not null default false;\nalter table listings add column if not exists boost_requested boolean not null default false;\nalter table listings add column if not exists boost_done_at timestamptz;\nalter table listings add column if not exists boost_done_by uuid references admin_users(id);\n\n-- What a payment covers, discount and promo code\nalter table payments add column if not exists items jsonb not null default '[]';   -- [{key, label, amount}]\nalter table payments add column if not exists subtotal int;\nalter table payments add column if not exists discount int not null default 0;\nalter table payments add column if not exists applied_at timestamptz;              -- effects applied (featured on, banner live…)\n\n-- Promo codes: description and which purposes they work for\nalter table promo_codes add column if not exists description text;\nalter table promo_codes add column if not exists purposes text[];                   -- null = all\nalter table promo_codes add column if not exists max_uses_per_phone int;\ncreate table if not exists promo_code_uses (\n  id bigint generated always as identity primary key,\n  promo_code_id int not null references promo_codes(id),\n  payment_id uuid references payments(id),\n  phone text,\n  created_at timestamptz not null default now()\n);\n\n-- Banner prices (set by admin) per placement and number of days\ncreate table if not exists banner_pricing (\n  id int generated always as identity primary key,\n  placement text not null,\n  days int not null check (days > 0),\n  price int not null check (price >= 0),\n  is_active boolean not null default true,\n  unique (placement, days)\n);\nalter table banner_pricing enable row level security;\ncreate policy \"public read banner pricing\" on banner_pricing for select using (is_active);\n\n-- Banner booking details\nalter table banners add column if not exists days int;\nalter table banners add column if not exists price int;\nalter table banners add column if not exists reject_reason text;\nalter table banners add column if not exists contact_whatsapp text;\nalter table banners add column if not exists approved_by uuid references admin_users(id);\nalter table banners add column if not exists approved_at timestamptz;\n\n-- Design service price + banner rules live in site_settings (public.banner_settings)\ninsert into site_settings (key, value)\nvalues ('public.banner_settings', '{\"design_price\": null, \"popup_enabled\": false, \"max_per_placement\": 5}')\non conflict (key) do nothing;\n\n-- Count a banner view (called in batches by the website)\ncreate or replace function add_banner_views(p_ids uuid[]) returns void\nlanguage sql as $$\n  insert into banner_stats (banner_id, day, views)\n  select id, (now() at time zone 'Asia/Karachi')::date, 1 from unnest(p_ids) as id\n  on conflict (banner_id, day) do update set views = banner_stats.views + 1;\n$$;\n"},{"name":"20261122000000_rishta.sql","sql":"-- =====================================================================\n-- Phase 7: Rishta (private matrimonial section)\n-- =====================================================================\n\n-- One-time login codes (stored hashed). Locally the code is shown on screen;\n-- on the live site it is sent by SMS / WhatsApp.\ncreate table if not exists rishta_otps (\n  id bigint generated always as identity primary key,\n  phone text not null,\n  code_hash text not null,\n  attempts int not null default 0,\n  expires_at timestamptz not null,\n  used_at timestamptz,\n  created_at timestamptz not null default now()\n);\ncreate index if not exists rishta_otps_phone_idx on rishta_otps (phone, created_at desc);\nalter table rishta_otps enable row level security;\n\n-- Profile extras\nalter table rishta_profiles add column if not exists full_name text;            -- private, never shown to members\nalter table rishta_profiles add column if not exists views int not null default 0;\nalter table rishta_profiles add column if not exists last_active_at timestamptz;\nalter table rishta_profiles add column if not exists hidden_reason text;\ncreate index if not exists rishta_profiles_search_idx on rishta_profiles (status, gender, date_of_birth);\n\n-- Photos: original (private), watermarked and blurred versions\nalter table rishta_photos add column if not exists watermarked_path text;\nalter table rishta_photos add column if not exists blurred_path text;\nalter table rishta_photos add column if not exists sort_order int not null default 0;\nalter table rishta_photos add column if not exists is_rejected boolean not null default false;\n\n-- Interests: photo sharing after acceptance\nalter table rishta_interests add column if not exists photos_shared_by_receiver boolean not null default false;\nalter table rishta_interests add column if not exists photos_shared_by_sender boolean not null default false;\nalter table rishta_interests add column if not exists mediation_note text;\nalter table rishta_interests add column if not exists mediation_status text check (mediation_status in ('open', 'in_progress', 'done'));\nalter table rishta_interests add column if not exists handled_by uuid references admin_users(id);\n\n-- Success stories (only with permission of both families; added by admin)\ncreate table if not exists rishta_stories (\n  id int generated always as identity primary key,\n  title_en text not null,\n  title_ur text not null,\n  body_en text not null default '',\n  body_ur text not null default '',\n  city text,\n  is_published boolean not null default false,\n  created_at timestamptz not null default now()\n);\nalter table rishta_stories enable row level security;\ncreate policy \"public read rishta stories\" on rishta_stories for select using (is_published);\n\n-- Plan settings (admin editable)\nupdate site_settings set value = value\n  || jsonb_build_object('premium_price', coalesce(value->'premium_price', 'null'::jsonb))\n  || jsonb_build_object('premium_days', coalesce(value->'premium_days', '90'::jsonb))\n  || jsonb_build_object('interests_per_day', coalesce(value->'interests_per_day', '10'::jsonb))\n  || jsonb_build_object('premium_interests_per_day', coalesce(value->'premium_interests_per_day', '30'::jsonb))\n  || jsonb_build_object('coordinator_fee', coalesce(value->'coordinator_fee', 'null'::jsonb))\n  where key = 'public.rishta_plan';\ninsert into site_settings (key, value) values ('public.rishta_plan', '{\"days\":90,\"price\":1000,\"premium_price\":null,\"premium_days\":90,\"interests_per_day\":10,\"premium_interests_per_day\":30,\"coordinator_fee\":null}')\n  on conflict (key) do nothing;\nupdate site_settings set value = '{\"enabled\": false, \"days\": 90}' where key = 'public.rishta_free_mode' and not (value ? 'days');\n"},{"name":"20261123000000_home_rishta_blog.sql","sql":"-- =====================================================================\n-- Rishta on the home page + Phase 8 (pages and blog)\n-- =====================================================================\n\n-- Home page Rishta section (after service providers)\ninsert into homepage_sections (key, is_enabled, sort_order)\nselect 'rishta', true, coalesce((select sort_order from homepage_sections where key = 'services'), 9) + 0\nwhere not exists (select 1 from homepage_sections where key = 'rishta');\nupdate homepage_sections set sort_order = sort_order + 1\n where key <> 'rishta' and sort_order >= (select sort_order from homepage_sections where key = 'rishta')\n   and key not in ('top_bar', 'offer_bar', 'hero', 'trust_points', 'categories', 'featured', 'wide_banner', 'fresh_ads', 'seasonal', 'services');\n\n-- Rishta preview for visitors (admin can switch off)\ninsert into site_settings (key, value) values ('public.rishta_preview', '{\"enabled\": true}') on conflict (key) do nothing;\n\n-- Pages: when edited and by whom; which pages appear in the footer/app menu\nalter table pages add column if not exists updated_by uuid references admin_users(id);\nalter table pages add column if not exists needs_owner_content boolean not null default false;\n\n-- Blog: Urdu/English pair, related ads, views, reading time\nalter table blog_posts add column if not exists translation_of uuid references blog_posts(id);\nalter table blog_posts add column if not exists related_category_id int references categories(id);\nalter table blog_posts add column if not exists views int not null default 0;\nalter table blog_posts add column if not exists reading_minutes int;\nalter table blog_posts add column if not exists updated_by uuid references admin_users(id);\nalter table blog_categories add column if not exists sort_order int not null default 0;\ncreate index if not exists blog_posts_public_idx on blog_posts (locale, status, published_at desc);\n\ninsert into blog_categories (slug, name_en, name_ur, sort_order) values\n  ('buying-selling', 'Buying and selling', 'خرید و فروخت', 1),\n  ('safety', 'Safety tips', 'حفاظتی ہدایات', 2),\n  ('property', 'Property and rent', 'پراپرٹی اور کرایہ', 3),\n  ('vehicles', 'Vehicles', 'گاڑیاں', 4),\n  ('mawaishi', 'Mawaishi and agriculture', 'مویشی اور زراعت', 5),\n  ('jobs-services', 'Jobs and services', 'نوکریاں اور سروسز', 6),\n  ('local-news', 'Okara local', 'اوکاڑہ کی خبریں', 7)\non conflict (slug) do nothing;\n\ninsert into authors (name, bio) select 'Apna Okara Team', 'The team behind Apna Okara.' where not exists (select 1 from authors);\n"},{"name":"20261123100000_contact_messages.sql","sql":"-- Contact form messages (Contact Us page)\ncreate table if not exists contact_messages (\n  id bigint generated always as identity primary key,\n  name text not null,\n  phone text,\n  email text,\n  subject text,\n  message text not null,\n  locale text not null default 'en',\n  status text not null default 'new' check (status in ('new', 'replied', 'closed')),\n  handled_by uuid references admin_users(id),\n  created_at timestamptz not null default now()\n);\nalter table contact_messages enable row level security;\n"},{"name":"20261124000000_growth_notifications.sql","sql":"-- Phase 10: push notifications, reminders, referrals, daily posts, backups\n\n-- ---------- Push notifications (app) ----------\ncreate table if not exists push_devices (\n  id bigint generated always as identity primary key,\n  token text unique not null,             -- Expo push token\n  platform text not null default 'android' check (platform in ('android', 'ios', 'web')),\n  locale text not null default 'ur' check (locale in ('en', 'ur')),\n  notify_ads boolean not null default true,        -- my ads: approved / rejected / expiring\n  notify_follows boolean not null default true,    -- new ads in followed categories\n  notify_rishta boolean not null default true,\n  is_active boolean not null default true,         -- false when Expo says the token is dead\n  created_at timestamptz not null default now(),\n  last_seen_at timestamptz not null default now()\n);\n\n-- Ads this device posted / manages (proved with reference + phone)\ncreate table if not exists push_device_listings (\n  device_id bigint not null references push_devices(id) on delete cascade,\n  listing_id uuid not null references listings(id) on delete cascade,\n  primary key (device_id, listing_id)\n);\n\n-- \"Tell me about new ads in Mobiles in Okara\"\ncreate table if not exists push_follows (\n  id bigint generated always as identity primary key,\n  device_id bigint not null references push_devices(id) on delete cascade,\n  category_id int not null references categories(id) on delete cascade,\n  city_id int references cities(id) on delete cascade,\n  last_notified_at timestamptz,\n  created_at timestamptz not null default now(),\n  unique (device_id, category_id, city_id)\n);\n\ncreate table if not exists push_device_rishta (\n  device_id bigint not null references push_devices(id) on delete cascade,\n  account_id uuid not null references rishta_accounts(id) on delete cascade,\n  primary key (device_id, account_id)\n);\n\n-- Outbox: every push is written here first, then sent (and kept as a record)\ncreate table if not exists push_messages (\n  id bigint generated always as identity primary key,\n  device_id bigint not null references push_devices(id) on delete cascade,\n  kind text not null,                     -- ad_approved, ad_rejected, ad_expiring, follow_new, rishta_interest, rishta_accepted, broadcast\n  title text not null,\n  body text not null,\n  data jsonb not null default '{}',       -- { url: \"/ad/...\" } opened when tapped\n  dedupe_key text unique,                 -- stops the same message twice\n  status text not null default 'queued' check (status in ('queued', 'sent', 'failed', 'dry_run')),\n  error text,\n  ticket_id text,\n  created_at timestamptz not null default now(),\n  sent_at timestamptz\n);\ncreate index if not exists push_messages_queue_idx on push_messages (created_at) where status = 'queued';\n\nalter table push_devices enable row level security;\nalter table push_device_listings enable row level security;\nalter table push_follows enable row level security;\nalter table push_device_rishta enable row level security;\nalter table push_messages enable row level security;\n\n-- ---------- Expiry reminders ----------\ncreate table if not exists listing_reminders (\n  id bigint generated always as identity primary key,\n  listing_id uuid not null references listings(id) on delete cascade,\n  channel text not null check (channel in ('whatsapp', 'push')),\n  kind text not null default 'expiring' check (kind in ('expiring', 'expired')),\n  sent_by uuid references admin_users(id),\n  created_at timestamptz not null default now()\n);\ncreate index if not exists listing_reminders_listing_idx on listing_reminders (listing_id);\nalter table listing_reminders enable row level security;\n\n-- ---------- Referrals ----------\ncreate table if not exists referral_codes (\n  phone text primary key,\n  code text unique not null,\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists referrals (\n  id bigint generated always as identity primary key,\n  referrer_phone text not null references referral_codes(phone),\n  referred_phone text not null,\n  listing_id uuid references listings(id) on delete set null,\n  status text not null default 'pending' check (status in ('pending', 'qualified', 'rejected')),\n  reject_reason text,\n  created_at timestamptz not null default now(),\n  qualified_at timestamptz,\n  unique (referred_phone)                 -- a new member can be referred only once\n);\ncreate index if not exists referrals_referrer_idx on referrals (referrer_phone, status);\n\ncreate table if not exists referral_rewards (\n  id bigint generated always as identity primary key,\n  phone text not null references referral_codes(phone),\n  promo_code_id int not null references promo_codes(id),\n  referrals_used int not null,\n  created_at timestamptz not null default now()\n);\n\nalter table referral_codes enable row level security;\nalter table referrals enable row level security;\nalter table referral_rewards enable row level security;\n\n-- A promo code can be locked to one phone (referral rewards)\nalter table promo_codes add column if not exists only_phone text;\n\ninsert into site_settings (key, value) values\n  ('public.referral', '{\"enabled\": true, \"needed\": 5, \"reward_days\": 7}'),\n  ('public.push', '{\"follow_gap_hours\": 6, \"expiring_hours\": 48}')\non conflict (key) do nothing;\n\n-- ---------- Backups ----------\ncreate table if not exists backups (\n  id bigint generated always as identity primary key,\n  file_name text not null,\n  size_bytes bigint,\n  status text not null default 'done' check (status in ('done', 'failed')),\n  error text,\n  started_by uuid references admin_users(id),  -- null = automatic daily backup\n  created_at timestamptz not null default now()\n);\nalter table backups enable row level security;\n"},{"name":"20261124100000_backups_bucket.sql","sql":"-- Private bucket for daily database backups (Admin -> Backups)\ninsert into storage.buckets (id, name, public) values ('backups', 'backups', false) on conflict (id) do nothing;\n"},{"name":"20261125000000_security_hardening.sql","sql":"-- Security hardening before launch\n\n-- 1) Admin login lockout kept in the database (works across all server copies on Vercel)\ncreate table if not exists admin_login_attempts (\n  key text primary key,                     -- 'email:<email>' or 'ip:<address>'\n  failures int not null default 0,\n  locked_until timestamptz,\n  updated_at timestamptz not null default now()\n);\nalter table admin_login_attempts enable row level security;\n\n-- 2) Secret manage code for sellers (needed to mark sold / reply to reviews).\n--    Only a hash is stored; the code itself is shown once to the seller.\nalter table listings add column if not exists manage_key_hash text;\n\n-- 3) Fake / reused payment protection\nalter table payments add column if not exists screenshot_hash text;\nalter table payments add column if not exists transaction_key text;  -- normalised TID (upper case, no spaces)\nupdate payments set transaction_key = upper(regexp_replace(transaction_id, '\\s|-', '', 'g')) where transaction_id is not null and transaction_key is null;\ncreate index if not exists payments_transaction_key_idx on payments (method, transaction_key) where transaction_key is not null;\ncreate index if not exists payments_screenshot_hash_idx on payments (screenshot_hash) where screenshot_hash is not null;\n\n-- 4) Row Level Security on every public table (no public policies: the website reads\n--    through the server only, so the public Supabase API can never read these tables)\ndo $$\ndeclare t record;\nbegin\n  for t in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace\n            where n.nspname = 'public' and c.relkind = 'r' and not c.relrowsecurity loop\n    execute format('alter table public.%I enable row level security', t.relname);\n  end loop;\nend $$;\n\n-- 5) Remove every \"public read\" policy. The website and app read only through the\n--    server (direct database connection), so the public Supabase API needs no access.\n--    Without this, the anon key could read seller phone numbers and reviewer phones.\ndo $$\ndeclare p record;\nbegin\n  for p in select policyname, tablename from pg_policies where schemaname = 'public' loop\n    execute format('drop policy if exists %I on public.%I', p.policyname, p.tablename);\n  end loop;\nend $$;\n"},{"name":"20261125100000_rishta_view_limit.sql","sql":"-- Rishta: record which profiles a member opens (stops mass copying of girls' / boys' profiles)\ncreate table if not exists rishta_profile_views (\n  viewer_profile_id uuid not null references rishta_profiles(id) on delete cascade,\n  viewed_profile_id uuid not null references rishta_profiles(id) on delete cascade,\n  day date not null default (now() at time zone 'Asia/Karachi')::date,\n  created_at timestamptz not null default now(),\n  primary key (viewer_profile_id, viewed_profile_id, day)\n);\nalter table rishta_profile_views enable row level security;\n"},{"name":"20261125200000_payment_proof.sql","sql":"-- Fake / reused payment protection\n-- transaction_key: the transaction ID cleaned up (upper case, only letters and digits)\n-- screenshot_hash: fingerprint of the screenshot (it is part of the file name)\ncreate or replace function payments_fill_proof() returns trigger language plpgsql as $$\nbegin\n  new.transaction_key := nullif(upper(regexp_replace(coalesce(new.transaction_id, ''), '[^A-Za-z0-9]', '', 'g')), '');\n  new.screenshot_hash := substring(coalesce(new.screenshot_path, '') from '([0-9a-f]{40})\\.webp$');\n  return new;\nend $$;\n\ndrop trigger if exists payments_fill_proof on payments;\ncreate trigger payments_fill_proof before insert or update of transaction_id, screenshot_path on payments\n  for each row execute function payments_fill_proof();\n\nupdate payments set transaction_id = transaction_id;  -- fill the new columns for old rows\n\n-- Older duplicates (same method + transaction ID, still open): keep the first, reject the rest\nupdate payments p set status = 'rejected', reject_reason = coalesce(p.reject_reason, 'Duplicate transaction ID (rejected automatically)')\n where p.transaction_key is not null and p.status in ('pending', 'verified')\n   and exists (select 1 from payments o where o.method = p.method and o.transaction_key = p.transaction_key\n                  and o.status in ('pending', 'verified') and o.created_at < p.created_at);\n\n-- The same transaction ID can never be open / accepted twice (a rejected one may be sent again)\ncreate unique index if not exists payments_one_open_per_tid on payments (method, transaction_key)\n  where transaction_key is not null and status in ('pending', 'verified');\n"},{"name":"20261126000000_nayapay.sql","sql":"-- NayaPay as a payment method (same as JazzCash / Easypaisa: account title + number)\nalter type payment_method add value if not exists 'nayapay' after 'easypaisa';\n"},{"name":"20261127000000_rishta_email_login.sql","sql":"-- Rishta login by email code (phone number still required and kept on the account)\nalter table rishta_accounts add column if not exists email text;\ncreate unique index if not exists rishta_accounts_email_key on rishta_accounts (lower(email)) where email is not null;\nalter table rishta_otps add column if not exists email text;\nalter table rishta_otps alter column phone drop not null;\ncreate index if not exists rishta_otps_email_idx on rishta_otps (lower(email), created_at desc) where email is not null;\n"},{"name":"20261128000000_sample_ads.sql","sql":"-- Sample ads (show new visitors how the site looks). Clearly labelled, no contact buttons,\n-- never in Google / sitemap, and they end by themselves like any ad.\nalter table listings add column if not exists is_sample boolean not null default false;\n"},{"name":"20261128100000_one_time_provider_plan.sql","sql":"-- Service providers and businesses: one-time fee, no renewal (listing runs 10 years).\n-- Business Rs 2,000, service providers Rs 1,000. Ads already posted are not changed.\nupdate pricing set duration_days = 3650, price = 1000 where model = 'services' and category_id is null and duration_days = 60;\nupdate pricing set duration_days = 3650, price = 2000 where model = 'business' and category_id is null and duration_days = 60;\ninsert into pricing (model, duration_days, price)\n  select m, 3650, p from (values ('services'::model_type, 1000), ('business'::model_type, 2000)) v(m, p)\n  where not exists (select 1 from pricing x where x.model = v.m and x.category_id is null and x.duration_days = 3650);\n-- category-specific prices for 2 months become one-time prices too\nupdate pricing set duration_days = 3650 where model in ('services', 'business') and category_id is not null and duration_days = 60;\n-- Free Mode: free service / business listings also last\nupdate site_settings\n   set value = jsonb_set(jsonb_set(value, '{days_by_model,services}', '3650'), '{days_by_model,business}', '3650')\n where key = 'public.free_mode';\n"},{"name":"20261129000000_first_blog_posts.sql","sql":"-- First 5 Urdu blog posts (only added if the slug is not there yet).\ninsert into blog_posts (slug, locale, title, excerpt, body, category_id, author_id, faq, seo_title, seo_description, focus_keyword, status, published_at, reading_minutes)\nselect v.slug, 'ur', v.title, v.excerpt, v.body,\n       (select id from blog_categories where slug = v.cat),\n       (select id from authors order by id limit 1),\n       v.faq::jsonb, v.title, v.excerpt, v.kw, 'published', now() - (v.n || ' hours')::interval, v.mins\nfrom (values\n(1, 'apna-okara-par-ishtehar-kaise-lagayen', 'buying-selling', 'اپنا اوکاڑہ پر اشتہار کیسے لگائیں؟ مکمل طریقہ', 'اوکاڑہ، ساہیوال اور پاکپتن میں کچھ بیچنا ہے؟ صرف 2 منٹ میں اپنا اشتہار لگائیں۔ یہ رہا قدم بہ قدم طریقہ۔', 'اشتہار کیسے لگائیں', 3,\n$md$\nگھر میں پڑا پرانا موبائل ہو، موٹر سائیکل ہو، فرنیچر ہو یا کرائے کا مکان، **اپنا اوکاڑہ** پر آپ اپنے ہی علاقے کے خریداروں تک آسانی سے پہنچ سکتے ہیں۔ نہ لاگ ان کی ضرورت، نہ لمبا فارم۔\n\n## اشتہار لگانے کا طریقہ\n\n1. ویب سائٹ پر اوپر **\"اشتہار لگائیں\"** کا بٹن دبائیں۔\n2. اپنی **کیٹیگری** چنیں، مثلاً موبائل، گاڑیاں، پراپرٹی یا مویشی۔\n3. اچھا سا **عنوان** لکھیں، جیسے \"Honda CD 70، ماڈل 2021، اوکاڑہ نمبر\"۔\n4. **قیمت** اور تفصیل لکھیں: حالت، ماڈل، کتنا استعمال ہوا۔\n5. **تصاویر** لگائیں۔ دن کی روشنی میں صاف تصاویر سب سے زیادہ کام کرتی ہیں۔\n6. اپنا **شہر** اور **فون نمبر** لکھیں۔\n7. اشتہار کی مدت چنیں اور ادائیگی کریں: جاز کیش، ایزی پیسہ، نیا پے یا بینک ٹرانسفر۔\n\nادائیگی کے بعد ہماری ٹیم اشتہار چیک کرتی ہے اور منظوری کے بعد وہ سائٹ پر لگ جاتا ہے۔ آپ کو ایک **ریفرنس نمبر** (جیسے AO-10001) ملتا ہے جس سے آپ اپنا اشتہار بعد میں دیکھ سکتے ہیں۔\n\n## اشتہار جلدی بکے، اس کے لیے\n\n- **سچی قیمت** لکھیں۔ بہت زیادہ قیمت دیکھ کر لوگ آگے بڑھ جاتے ہیں۔\n- **کم از کم 3 تصاویر** لگائیں: سامنے، پیچھے اور کوئی خرابی ہو تو وہ بھی۔\n- **فون اٹھائیں** اور واٹس ایپ کا جواب جلدی دیں۔\n- چاہیں تو اشتہار کو **فیچرڈ** بنائیں تاکہ وہ سب سے اوپر نظر آئے۔\n\n## اشتہار بک جائے تو؟\n\n**\"میرے اشتہار\"** میں جا کر اسے \"بک گیا\" کر دیں، تاکہ لوگ فون نہ کرتے رہیں۔\n$md$,\n'[{\"q\":\"کیا اشتہار لگانے کے لیے اکاؤنٹ بنانا ضروری ہے؟\",\"a\":\"نہیں۔ صرف فون نمبر کافی ہے۔\"},{\"q\":\"اشتہار کب لگتا ہے؟\",\"a\":\"ادائیگی چیک ہونے کے بعد ہماری ٹیم اسے منظور کرتی ہے، عام طور پر کچھ ہی گھنٹوں میں۔\"}]'),\n\n(2, 'online-khareed-o-farokht-mein-dhokay-se-bachen', 'safety', 'آن لائن خرید و فروخت میں دھوکے سے کیسے بچیں؟ 8 ضروری باتیں', 'ایڈوانس پیسے، جعلی اسکرین شاٹ اور \"کورئیر سے بھیج دوں گا\"۔ یہ ہیں عام دھوکے اور ان سے بچنے کے آسان طریقے۔', 'آن لائن دھوکہ', 4,\n$md$\nآن لائن خرید و فروخت آسان ہے، مگر تھوڑی سی احتیاط آپ کو بڑے نقصان سے بچا سکتی ہے۔ یہ 8 باتیں ہمیشہ یاد رکھیں۔\n\n## 1. ایڈوانس پیسے نہ بھیجیں\n\nچیز دیکھے بغیر کبھی پیسے نہ بھیجیں، چاہے بیچنے والا کتنا ہی جلدی کرے۔\n\n## 2. آمنے سامنے ملیں\n\nکسی **عوامی جگہ** پر دن کے وقت ملیں، جیسے بازار یا کسی بینک کے سامنے۔ کسی کو ساتھ لے جائیں۔\n\n## 3. جعلی اسکرین شاٹ سے ہوشیار\n\nاگر آپ بیچ رہے ہیں تو صرف اسکرین شاٹ پر بھروسہ نہ کریں۔ اپنی **جاز کیش یا ایزی پیسہ ایپ کھول کر** دیکھیں کہ پیسے واقعی آئے ہیں۔\n\n## 4. \"میں باہر ہوں، کورئیر کر دوں گا\"\n\nیہ سب سے عام دھوکہ ہے۔ جو بندہ ملنے سے انکار کرے، اس سے سودا نہ کریں۔\n\n## 5. موبائل کا IMEI چیک کریں\n\nپرانا موبائل لیتے وقت **\\*8484#** ملا کر یا PTA کی سائٹ سے IMEI چیک کریں کہ فون رجسٹرڈ ہے۔\n\n## 6. گاڑی کے کاغذات دیکھیں\n\nموٹر سائیکل یا گاڑی کی **رجسٹریشن، ٹیکس اور اصل کاغذات** دیکھیں، اور چیسس نمبر ملائیں۔\n\n## 7. OTP یا کوڈ کسی کو نہ بتائیں\n\nکوئی بھی آپ سے فون پر آیا ہوا **کوڈ** مانگے تو سمجھ جائیں کہ دھوکہ ہے۔ اپنا اوکاڑہ کبھی آپ سے کوڈ نہیں مانگتا۔\n\n## 8. مشکوک اشتہار کی رپورٹ کریں\n\nہر اشتہار پر **\"رپورٹ\"** کا بٹن ہے۔ کوئی دھوکے باز لگے تو رپورٹ کریں، ہماری ٹیم فوراً دیکھتی ہے۔\n$md$,\n'[{\"q\":\"اگر میرے ساتھ دھوکہ ہو جائے تو کیا کروں؟\",\"a\":\"اشتہار پر رپورٹ کریں، ہمیں واٹس ایپ کریں اور ضرورت ہو تو FIA سائبر کرائم کو شکایت کریں۔\"}]'),\n\n(3, 'purani-motorcycle-khareedne-se-pehle', 'vehicles', 'پرانی موٹر سائیکل خریدنے سے پہلے یہ 10 چیزیں ضرور چیک کریں', 'اوکاڑہ اور ساہیوال میں پرانی بائیک لینے کا سوچ رہے ہیں؟ یہ چیک لسٹ آپ کو غلط سودے سے بچائے گی۔', 'پرانی موٹر سائیکل', 4,\n$md$\nپرانی موٹر سائیکل اچھا اور سستا سودا ہو سکتی ہے، بشرطیکہ آپ اسے اچھی طرح چیک کر لیں۔ یہ رہی ہماری چیک لسٹ:\n\n## کاغذات\n\n1. **رجسٹریشن بک** اصل ہو اور نام بیچنے والے کا ہو، یا ٹرانسفر کے کاغذ پورے ہوں۔\n2. **چیسس اور انجن نمبر** کاغذات سے ملائیں۔\n3. **ٹوکن ٹیکس** کب تک جمع ہے، یہ دیکھیں۔\n\n## انجن اور چلانا\n\n4. **ٹھنڈا انجن** اسٹارٹ کروائیں۔ پہلی کک یا سیلف پر اسٹارٹ ہونا اچھی نشانی ہے۔\n5. **دھواں** دیکھیں۔ نیلا یا کالا دھواں انجن کے کام کی نشانی ہو سکتا ہے۔\n6. **چلا کر دیکھیں**: گیئر آسانی سے بدلیں، کلچ نہ پھسلے، بریک ٹھیک لگیں۔\n\n## باڈی اور پرزے\n\n7. **ٹائر** اور **چین سیٹ** کی حالت دیکھیں۔ یہ بدلوانے پڑیں تو خرچہ بڑھتا ہے۔\n8. **فریم** پر ویلڈنگ یا ٹیڑھا پن تو نہیں؟ یہ حادثے کی نشانی ہو سکتی ہے۔\n9. **لائٹس، ہارن اور انڈیکیٹر** چیک کریں۔\n\n## قیمت\n\n10. اپنا اوکاڑہ پر **اسی ماڈل کے دوسرے اشتہار** دیکھیں تاکہ اندازہ ہو کہ مناسب قیمت کیا ہے۔\n\n> مشورہ: اگر آپ کو انجن کی سمجھ نہیں تو کسی جاننے والے مستری کو ساتھ لے جائیں۔ چند سو روپے کی فیس ہزاروں کا نقصان بچا سکتی ہے۔\n$md$,\n'[{\"q\":\"کیا ٹرانسفر کروانا ضروری ہے؟\",\"a\":\"جی ہاں۔ بائیک اپنے نام ٹرانسفر کروائیں تاکہ بعد میں کوئی مسئلہ نہ ہو۔\"}]'),\n\n(4, 'qurbani-ka-janwar-khareedne-ki-rehnumai', 'mawaishi', 'قربانی کا جانور خریدنے کی آسان رہنمائی', 'بکرا، گائے یا بیل: صحت مند جانور کیسے پہچانیں اور منڈی کے رش سے پہلے گھر بیٹھے کیسے تلاش کریں۔', 'قربانی کا جانور', 4,\n$md$\nاوکاڑہ، ساہیوال اور پاکپتن مویشیوں کے لیے مشہور علاقے ہیں۔ قربانی کا جانور لیتے وقت یہ باتیں ذہن میں رکھیں۔\n\n## عمر کا خیال رکھیں\n\nقربانی کے لیے جانور کی عمر پوری ہونا ضروری ہے۔ عمر کی شرائط کے بارے میں اپنے علاقے کے کسی **عالم** سے ضرور پوچھ لیں۔ عام طور پر **دانت** دیکھ کر عمر کا اندازہ لگایا جاتا ہے۔\n\n## صحت مند جانور کی نشانیاں\n\n- **آنکھیں** صاف اور چمکدار ہوں، پانی نہ بہہ رہا ہو۔\n- **ناک** گیلی اور صاف ہو۔\n- جانور **چست** ہو اور آرام سے چلے، لنگڑاتا نہ ہو۔\n- **چارہ** شوق سے کھائے۔\n- **کان، سینگ اور دم** میں کوئی ایسا نقص نہ ہو جو قربانی میں رکاوٹ بنے۔\n\n## منڈی سے پہلے آن لائن دیکھیں\n\nعید کے قریب منڈیوں میں رش اور قیمتیں دونوں بڑھ جاتی ہیں۔ اپنا اوکاڑہ کی **مویشی** کیٹیگری میں آپ اپنے قریب کے بیچنے والوں کے جانور تصاویر کے ساتھ دیکھ سکتے ہیں، پھر جا کر خود چیک کریں۔\n\n## بیچنے والوں کے لیے\n\nاگر آپ جانور بیچ رہے ہیں تو **دن کی روشنی میں** جانور کی پوری تصویر لگائیں، اور **وزن، عمر اور نسل** ضرور لکھیں۔ ایسے اشتہار زیادہ جلدی بکتے ہیں۔\n\n> جانور ہمیشہ خود دیکھ کر خریدیں، اور ایڈوانس رقم سوچ سمجھ کر دیں۔\n$md$,\n'[{\"q\":\"کیا میں گھر بیٹھے جانور خرید سکتا ہوں؟\",\"a\":\"آپ اشتہار دیکھ کر بیچنے والے سے بات کر سکتے ہیں، مگر خریدنے سے پہلے جانور خود جا کر ضرور دیکھیں۔\"}]'),\n\n(5, 'apna-hunar-aur-karobar-online-layen', 'jobs-services', 'کاریگر اور دکاندار: اپنا کام آن لائن کیسے لائیں؟', 'پلمبر، الیکٹریشن، ٹیوٹر یا دکان: ایک بار کی فیس میں اپنا کام اپنا اوکاڑہ پر لسٹ کریں اور نئے گاہک پائیں۔', 'کاروبار آن لائن', 3,\n$md$\nآج کل لوگ پلمبر، الیکٹریشن، ٹیوٹر یا اچھی دکان ڈھونڈنے کے لیے بھی پہلے موبائل پر تلاش کرتے ہیں۔ اگر آپ کا کام آن لائن نہیں، تو یہ گاہک آپ تک نہیں پہنچتے۔\n\n## اپنا اوکاڑہ پر لسٹنگ کیوں؟\n\n- **اپنے علاقے کے گاہک**: اوکاڑہ، ساہیوال اور پاکپتن کے لوگ۔\n- **سیدھا فون اور واٹس ایپ**: گاہک بٹن دبا کر آپ سے بات کرتا ہے، بیچ میں کوئی کمیشن نہیں۔\n- **ریویوز**: اچھے کام پر گاہک آپ کو ریویو دیتے ہیں، جس سے نئے لوگوں کا بھروسہ بڑھتا ہے۔\n- **ویریفائیڈ نشان**: کاغذات چیک ہونے کے بعد آپ کی لسٹنگ پر ✓ کا نشان لگ سکتا ہے۔\n\n## فیس صرف ایک بار\n\n| لسٹنگ | فیس |\n|---|---|\n| کاریگر / سروس (پلمبر، الیکٹریشن، ٹیوٹر وغیرہ) | 1,000 روپے، ایک بار |\n| کاروبار (دکان، کلینک، ریسٹورنٹ وغیرہ) | 2,000 روپے، ایک بار |\n\nہر مہینے یا ہر سال دوبارہ پیسے نہیں دینے۔\n\n## اچھی لسٹنگ کیسے بنائیں\n\n1. **صاف عنوان**: \"تجربہ کار الیکٹریشن، رینالہ خورد\" جیسا۔\n2. **اپنے کام کی تصاویر** لگائیں: دکان کا سامنے کا حصہ یا کیا ہوا کام۔\n3. **اوقات اور علاقہ** لکھیں کہ آپ کہاں کہاں جاتے ہیں۔\n4. فون پر **جلدی جواب** دیں۔ یہی سب سے بڑی مارکیٹنگ ہے۔\n\n**\"اشتہار لگائیں\"** دبائیں اور \"سروسز\" یا \"کاروبار\" کیٹیگری چنیں۔\n$md$,\n'[{\"q\":\"کیا ہر سال فیس دینی ہوگی؟\",\"a\":\"نہیں۔ کاریگر کے لیے 1,000 اور کاروبار کے لیے 2,000 روپے صرف ایک بار۔\"}]')\n) as v(n, slug, cat, title, excerpt, kw, mins, body, faq)\nwhere not exists (select 1 from blog_posts b where b.slug = v.slug);\n"},{"name":"20261129100000_first_blog_posts_en.sql","sql":"-- English versions of the first 5 blog posts (only added if the slug is not there yet).\ninsert into blog_posts (slug, locale, title, excerpt, body, category_id, author_id, faq, seo_title, seo_description, focus_keyword, status, published_at, reading_minutes)\nselect v.slug, 'en', v.title, v.excerpt, v.body,\n       (select id from blog_categories where slug = v.cat),\n       (select id from authors order by id limit 1),\n       v.faq::jsonb, v.title, v.excerpt, v.kw, 'published', now() - (v.n || ' hours')::interval, v.mins\nfrom (values\n(1, 'how-to-post-an-ad-on-apna-okara', 'buying-selling', 'How to post an ad on Apna Okara: step by step', 'Selling something in Okara, Sahiwal or Pakpattan? Post your ad in 2 minutes. Here is how.', 'post an ad', 3,\n$md$\nAn old phone, a motorcycle, furniture or a house for rent: on **Apna Okara** you reach buyers in your own area. No login and no long forms.\n\n## How to post an ad\n\n1. Tap **\"Post Ad\"** at the top of the site.\n2. Choose your **category**, for example Mobiles, Vehicles, Property or Mawaishi.\n3. Write a clear **title**, like \"Honda CD 70, 2021 model, Okara number\".\n4. Add the **price** and details: condition, model, how much it was used.\n5. Add **photos**. Clear photos taken in daylight work best.\n6. Choose your **city** and add your **phone number**.\n7. Choose how long the ad should run and pay with JazzCash, Easypaisa, NayaPay or bank transfer.\n\nAfter payment, our team checks the ad and puts it live once it is approved. You get a **reference number** (like AO-10001) to find your ad later.\n\n## Tips to sell faster\n\n- Write an **honest price**. A very high price makes people move on.\n- Add **at least 3 photos**: front, back, and any fault too.\n- **Answer calls** and reply on WhatsApp quickly.\n- Make your ad **Featured** so it shows at the top.\n\n## Sold it?\n\nOpen **\"My Ads\"** and mark it as sold, so people stop calling.\n$md$,\n'[{\"q\":\"Do I need an account to post an ad?\",\"a\":\"No. Your phone number is enough.\"},{\"q\":\"When does my ad go live?\",\"a\":\"After the payment is checked, our team approves it, usually within a few hours.\"}]'),\n\n(2, 'how-to-avoid-online-buying-and-selling-scams', 'safety', 'How to avoid scams when buying and selling online: 8 tips', 'Advance payments, fake screenshots and \"I will send it by courier\". The common scams and how to avoid them.', 'online scams', 4,\n$md$\nBuying and selling online is easy, and a little care can save you from a big loss. Always remember these 8 points.\n\n## 1. Do not send money in advance\n\nNever pay before you have seen the item, however much the seller rushes you.\n\n## 2. Meet face to face\n\nMeet in a **public place** in daylight, such as a market or outside a bank. Take someone with you.\n\n## 3. Watch out for fake screenshots\n\nIf you are selling, do not trust a screenshot alone. **Open your JazzCash or Easypaisa app** and check that the money has really arrived.\n\n## 4. \"I am abroad, I will send it by courier\"\n\nThis is the most common scam. Do not deal with anyone who refuses to meet.\n\n## 5. Check the phone's IMEI\n\nWhen buying a used phone, dial **\\*8484#** or use the PTA website to check that the IMEI is registered.\n\n## 6. Check vehicle papers\n\nFor a motorcycle or car, check the **registration, tax and original papers**, and match the chassis number.\n\n## 7. Never share an OTP or code\n\nIf anyone asks for a **code** you received on your phone, it is a scam. Apna Okara never asks you for a code.\n\n## 8. Report suspicious ads\n\nEvery ad has a **\"Report\"** button. If someone looks like a scammer, report it and our team checks it quickly.\n$md$,\n'[{\"q\":\"What should I do if I am scammed?\",\"a\":\"Report the ad, message us on WhatsApp, and if needed file a complaint with FIA Cyber Crime.\"}]'),\n\n(3, 'checklist-before-buying-a-used-motorcycle', 'vehicles', 'Buying a used motorcycle? Check these 10 things first', 'Thinking of buying a used bike in Okara or Sahiwal? This checklist will save you from a bad deal.', 'used motorcycle', 4,\n$md$\nA used motorcycle can be a good, cheap deal, as long as you check it properly. Here is our checklist:\n\n## Papers\n\n1. The **registration book** is original and in the seller's name, or the transfer papers are complete.\n2. Match the **chassis and engine numbers** with the papers.\n3. Check until when the **token tax** is paid.\n\n## Engine and test ride\n\n4. Start it with a **cold engine**. Starting on the first kick or self-start is a good sign.\n5. Look at the **smoke**. Blue or black smoke can mean engine work is needed.\n6. **Take a test ride**: gears change smoothly, the clutch does not slip, the brakes work well.\n\n## Body and parts\n\n7. Check the **tyres** and **chain set**. Replacing them adds to the cost.\n8. Look at the **frame** for welding or bends, which can be a sign of an accident.\n9. Check the **lights, horn and indicators**.\n\n## Price\n\n10. Look at **other ads for the same model** on Apna Okara to get an idea of a fair price.\n\n> Tip: if you do not know engines, take a mechanic you trust. A small fee can save you thousands.\n$md$,\n'[{\"q\":\"Do I need to transfer the bike to my name?\",\"a\":\"Yes. Transfer it to your name so there are no problems later.\"}]'),\n\n(4, 'guide-to-buying-a-qurbani-animal', 'mawaishi', 'A simple guide to buying a Qurbani animal', 'Goat, cow or bull: how to spot a healthy animal, and how to look from home before the mandi rush.', 'Qurbani animal', 4,\n$md$\nOkara, Sahiwal and Pakpattan are well known for livestock. Keep these points in mind when buying a Qurbani animal.\n\n## Mind the age\n\nThe animal must be old enough for Qurbani. Ask a **scholar** in your area about the age rules. Age is usually judged by looking at the **teeth**.\n\n## Signs of a healthy animal\n\n- **Eyes** are clean and bright, with no watering.\n- The **nose** is moist and clean.\n- The animal is **active** and walks easily, without limping.\n- It **eats** its fodder well.\n- There is no fault in the **ears, horns or tail** that would stop it being used for Qurbani.\n\n## Look online before the mandi\n\nClose to Eid, mandis get crowded and prices go up. In the **Mawaishi** category on Apna Okara you can see animals from sellers near you, with photos, and then go and check them yourself.\n\n## For sellers\n\nIf you are selling, add a full photo of the animal **in daylight**, and always write its **weight, age and breed**. These ads sell faster.\n\n> Always see the animal yourself before buying, and think carefully before paying any advance.\n$md$,\n'[{\"q\":\"Can I buy an animal from home?\",\"a\":\"You can look at ads and talk to the seller, but always go and see the animal yourself before you buy.\"}]'),\n\n(5, 'bring-your-skills-and-business-online', 'jobs-services', 'Workers and shopkeepers: how to bring your work online', 'Plumber, electrician, tutor or shop: list your work on Apna Okara for a one-time fee and get new customers.', 'business online', 3,\n$md$\nToday, people look on their phones first, even to find a plumber, an electrician, a tutor or a good shop. If your work is not online, these customers never reach you.\n\n## Why list on Apna Okara?\n\n- **Customers from your area**: people in Okara, Sahiwal and Pakpattan.\n- **Direct calls and WhatsApp**: customers tap a button and talk to you, with no commission in between.\n- **Reviews**: customers can review good work, which builds trust with new people.\n- **Verified badge**: after your papers are checked, your listing can show a ✓ badge.\n\n## Pay only once\n\n| Listing | Fee |\n|---|---|\n| Worker / service (plumber, electrician, tutor, etc.) | Rs 1,000, one time |\n| Business (shop, clinic, restaurant, etc.) | Rs 2,000, one time |\n\nNo monthly or yearly fee.\n\n## How to make a good listing\n\n1. **A clear title**, like \"Experienced electrician, Renala Khurd\".\n2. **Photos of your work**: the front of your shop, or work you have done.\n3. Write your **hours and the areas** you cover.\n4. **Answer calls quickly**. That is the best marketing.\n\nTap **\"Post Ad\"** and choose the \"Services\" or \"Business\" category.\n$md$,\n'[{\"q\":\"Do I pay every year?\",\"a\":\"No. Rs 1,000 for workers and Rs 2,000 for businesses, only once.\"}]')\n) as v(n, slug, cat, title, excerpt, kw, mins, body, faq)\nwhere not exists (select 1 from blog_posts b where b.slug = v.slug);\n"},{"name":"20261130000000_payment_receipts.sql","sql":"-- What the server read from each payment screenshot (OCR): payment date/time, amount, transaction ID.\n-- Linked to payments by the screenshot fingerprint (payments.screenshot_hash).\ncreate table if not exists payment_receipts (\n  screenshot_hash text primary key,\n  paid_at timestamptz,            -- date + time shown on the screenshot (Pakistan time converted)\n  has_time boolean not null default false,\n  amount int,                     -- amount shown on the screenshot\n  transaction_id text,            -- transaction ID shown on the screenshot (cleaned: A-Z and 0-9)\n  file_time timestamptz,          -- when the screenshot file was made, as the phone reports it\n  ocr_text text,\n  read_ok boolean not null default false,  -- false when OCR found nothing useful\n  created_at timestamptz not null default now()\n);\ncreate index if not exists payment_receipts_tid_idx on payment_receipts (transaction_id) where transaction_id is not null;\nalter table payment_receipts enable row level security;  -- server only, no public access\n\n-- When the customer did not type a transaction ID, use the one read from the screenshot.\n-- Then the existing rule \"one open payment per transaction ID\" also blocks reused payments.\ncreate or replace function payments_fill_proof() returns trigger language plpgsql as $$\nbegin\n  new.screenshot_hash := substring(coalesce(new.screenshot_path, '') from '([0-9a-f]{40})\\.webp$');\n  if coalesce(new.transaction_id, '') = '' and new.screenshot_hash is not null then\n    select r.transaction_id into new.transaction_id from payment_receipts r where r.screenshot_hash = new.screenshot_hash;\n  end if;\n  new.transaction_key := nullif(upper(regexp_replace(coalesce(new.transaction_id, ''), '[^A-Za-z0-9]', '', 'g')), '');\n  return new;\nend $$;\n"}];
